SELECT COUNT(*) > 0 AS `EXISTS`
FROM T_USER
WHERE ID = #{id}

SELECT COUNT(*) > 0 AS `EXISTS`
FROM T_USER
WHERE EMAIL = #{email}

SELECT ID, NAME, PASSWORD, PASSWORD_SALT
FROM T_USER
WHERE ID = #{id}

SELECT ID, NAME, EMAIL
FROM T_USER
WHERE NAME = #{name}
  AND EMAIL = #{email}

  AND ID = #{id}

